; Contagion: a ladder cell for CellHack2.  GENERATED by cells/gen_contagion.py -- do not edit by hand.
; Written with AI help.
;
; Paste this whole file into the site.  It has no org/bits/section/%include on purpose: the server
; prepends `bits 64 / org CODE_BASE / default rel / <cellhack.inc>` and runs `nasm -f bin`.
; CPU target: plain qemu64 (SSE2 only used).  No loops, no stack use.  Relies on: rax = 0 at entry
; (registers are reset before every call).  The bite and gate-1 paths leave with `jnz`/`jae EXIT_ADDR`
; and never touch the cell memory.
;
; Behaviour (1-3 and 6-7 are Scourge's, feeding floor 12 instead of 16)
;   1. An enemy next to me: bite it.  One enemy: that one.  Two or four: first of DOWN, LEFT, UP, RIGHT.
;      Exactly three: the one opposite the single non-enemy side.
;   2. Refill: an empty neighbour with an enemy beside or beyond it (view squares 6, 8, 10, 14, 16, 18)
;      is a freed front square: split into it when energy >= 12.  First of DOWN, RIGHT, UP, LEFT.
;   3. Otherwise split into the first empty neighbour of DOWN, RIGHT, UP, LEFT when energy >= 16, or
;      when 5 <= energy < 16 and no enemy is anywhere in the 5x5 view (from tick 2980: always);
;      with an enemy in view (before tick 2980) hold: rest, and stop being a scout.
;   4. Scout: at tick 0 the start cell, if within 10 squares of an edge, splits toward the side with the
;      most room and marks the child a scout (memory [1] bit 1, origin [2],[3], bearing [4], steps [5]).
;      Instead of a plain split (3, no enemy in view) a scout MOVEs along its bearing, at most 10 times;
;      blocked, out of steps, or at the origin square: it clears the bit and splits as usual.
;   5. Grab assist: no empty neighbour, energy >= 8, no enemy in the 5x5: feed the first friend
;      neighbour (UP, RIGHT, DOWN, LEFT) with energy <= 4 that has an empty neighbour.
;   6. No empty neighbour and energy >= 12: feed the poorest friend neighbour (ties UP, RIGHT, DOWN,
;      LEFT) if its energy <= energy - 4; from energy 47 on, if its energy <= 46.
;   7. Otherwise rest.
;
; Instruction counts per path (every executed instruction, including taken jumps and ret;
; in brackets the same path with taken jumps not counted):
;   bite (any adjacent enemy)                                      5  (4)
;   refill (freed front square, e >= 12)                          11 (10)
;   split, e >= 16                                                11 (10)
;   split, 5 <= e < 16, no enemy in the 5x5                          26 (26)
;   scout move                                                     40 (38)
;   split, 5 <= e < 16, enemy in the 5x5, tick >= 2980                25 (23)
;   hold (rest), 5 <= e < 16, enemy in the 5x5, tick < 2980           28 (27)
;   rest, e < 5, an empty neighbour                                17 (16)
;   rest, boxed, e < 8                                               17 (15)
;   grab assist / feed block: see sim/cells_ref.py make_contagion (longest well under 100).

start:
	movdqu		xmm0, [rdi + VIEW_CELLS + VIEW_UP]	; view idx 7..22
	pcmpeqb		xmm0, [kEnemy]
	pmovmskb	ecx, xmm0			; bits 0 UP, 4 LEFT, 6 RIGHT, 10 DOWN
	or		al, [abs bite_tbl + rcx]	; rax = 0 at entry: al = eat action, ZF = no enemy
	jnz		EXIT_ADDR			; bite: leave through the return address

slow:						; 5 instructions so far
	movdqu		xmm1, [rdi + VIEW_CELLS + 6]	; view idx 6..21
	pcmpeqb		xmm1, [kRefill]			; empty neighbours, enemies beside/beyond them
	pmovmskb	ecx, xmm1			; mask 0..7607
	mov		al, [abs act_tbl + rcx]		; split to take (0 = no empty neighbour)
	cmp		sil, [abs thr_tbl + rcx]	; energy it needs (12 refill, 16 other, 255 boxed)
	jae		EXIT_ADDR			; refill / split: 11 instructions
	test		al, al
	jz		boxed
	cmp		esi, 5
	jb		rest
	movdqu		xmm1, [rdi + VIEW_CELLS]	; view idx 0..15
	movdqu		xmm2, [rdi + VIEW_CELLS + 9]	; view idx 9..24
	pcmpeqb		xmm1, [kTwoLo]			; lane 12 (self) never matches
	pcmpeqb		xmm2, [kTwoHi]			; lane 3 (self) never matches
	por		xmm1, xmm2
	pmovmskb	r8d, xmm1
	test		r8d, r8d
	jnz		threat
	cmp		byte [rdx + 1], 1		; flags: 1 = plain cell
	jne		special
	ret					; split: no enemy in the 5x5
threat:
	cmp		dword [rdi + VIEW_TICK], 2980
	jae		EXIT_ADDR			; late: split anyway
	and		byte [rdx + 1], 0xFD		; hold: a scout stops here
rest:
	mov		al, ACT_REST
	ret

special:					; flags 0 (start cell, tick 0) or scout bit set
	test		byte [rdx + 1], 2
	jnz		scout
	mov		byte [rdx + 1], 1		; initialised
	cmp		dword [rdi + VIEW_TICK], 0
	jne		.plain				; only the start cell (tick 0) may send a scout
	movzx		ecx, word [rdi + VIEW_X]	; room LEFT
	movzx		r8d, word [rdi + VIEW_W]
	sub		r8d, ecx
	dec		r8d				; room RIGHT
	movzx		r9d, word [rdi + VIEW_Y]	; room UP
	movzx		r10d, word [rdi + VIEW_H]
	sub		r10d, r9d
	dec		r10d				; room DOWN
	mov		esi, ecx			; esi = least room
	cmp		esi, r8d
	cmova		esi, r8d
	cmp		esi, r9d
	cmova		esi, r9d
	cmp		esi, r10d
	cmova		esi, r10d
	cmp		esi, 10
	ja		.plain				; far from every edge: no scout
	mov		r11d, r9d			; most room so far (UP)
	xor		esi, esi			; bearing UP
	cmp		r8d, r11d
	jbe		.b1
	mov		r11d, r8d
	mov		esi, DIR_RIGHT
.b1:
	cmp		r10d, r11d
	jbe		.b2
	mov		r11d, r10d
	mov		esi, DIR_DOWN
.b2:
	cmp		ecx, r11d
	jbe		.b3
	mov		esi, DIR_LEFT
.b3:
	mov		byte [rdx + 1], 3		; initialised + scout (copied to the child)
	mov		[rdx + 2], cl			; origin x
	mov		[rdx + 3], r9b			; origin y
	mov		[rdx + 4], sil			; bearing
	mov		byte [rdx + 5], 10		; steps left
	lea		eax, [rsi + ACT_SPLIT]		; the scout is born on the bearing side
.plain:
	ret

scout:
	mov		cl, [rdi + VIEW_X]
	mov		ch, [rdi + VIEW_Y]
	cmp		cx, [rdx + 2]
	je		scout_end			; the origin cell itself
	cmp		byte [rdx + 5], 0
	je		scout_end			; out of steps
	movzx		ecx, byte [rdx + 4]		; bearing
	movzx		r8d, byte [abs dir_idx + rcx]
	cmp		byte [rdi + VIEW_CELLS + r8], CELL_EMPTY
	jne		scout_end			; blocked
	dec		byte [rdx + 5]
	lea		eax, [rcx + ACT_MOVE]
	ret
scout_end:
	mov		byte [rdx + 1], 1
	ret					; al = the plain split

boxed:
	cmp		esi, 8
	jb		rest
	movdqu		xmm1, [rdi + VIEW_CELLS]	; view idx 0..15
	movdqu		xmm2, [rdi + VIEW_CELLS + 9]	; view idx 9..24
	pxor		xmm3, xmm3
	pxor		xmm4, xmm4
	pcmpeqb		xmm3, xmm1			; empty squares, idx 0..15
	pcmpeqb		xmm4, xmm2			; empty squares, idx 9..24
	pcmpeqb		xmm1, [kTwoLo]
	pcmpeqb		xmm2, [kTwoHi]
	por		xmm1, xmm2
	pmovmskb	r8d, xmm1
	test		r8d, r8d
	jnz		feed_d				; enemy in the 5x5: no grab assist
	pmovmskb	r9d, xmm3
	pmovmskb	r10d, xmm4
	shl		r10d, 9
	or		r9d, r10d			; bit i = view square i empty
	cmp		byte [rdi + VIEW_CELLS + 7], CELL_FRIEND	; grab: up
	jne		.g_up
	cmp		byte [rdi + VIEW_ENERGIES + 7], 4
	ja		.g_up
	test		r9d, 0x144			; an empty neighbour of it
	jz		.g_up
	mov		al, ACT_FEED + DIR_UP
	ret
.g_up:
	cmp		byte [rdi + VIEW_CELLS + 13], CELL_FRIEND	; grab: right
	jne		.g_right
	cmp		byte [rdi + VIEW_ENERGIES + 13], 4
	ja		.g_right
	test		r9d, 0x44100			; an empty neighbour of it
	jz		.g_right
	mov		al, ACT_FEED + DIR_RIGHT
	ret
.g_right:
	cmp		byte [rdi + VIEW_CELLS + 17], CELL_FRIEND	; grab: down
	jne		.g_down
	cmp		byte [rdi + VIEW_ENERGIES + 17], 4
	ja		.g_down
	test		r9d, 0x450000			; an empty neighbour of it
	jz		.g_down
	mov		al, ACT_FEED + DIR_DOWN
	ret
.g_down:
	cmp		byte [rdi + VIEW_CELLS + 11], CELL_FRIEND	; grab: left
	jne		.g_left
	cmp		byte [rdi + VIEW_ENERGIES + 11], 4
	ja		.g_left
	test		r9d, 0x10440			; an empty neighbour of it
	jz		.g_left
	mov		al, ACT_FEED + DIR_LEFT
	ret
.g_left:
feed_d:
	cmp		esi, 12
	jb		rest
	lea		r9d, [rsi - 4]		; limit: poorest friend <= e - 4 ...
	mov		r10d, 46
	cmp		esi, 47
	cmovae		r9d, r10d			; ... or <= 46 for a capped donor
	mov		r8d, 255			; poorest friend energy so far
	mov		eax, ACT_REST
	cmp		byte [rdi + VIEW_CELLS + 7], CELL_FRIEND	; up
	jne		.n_up
	movzx		ecx, byte [rdi + VIEW_ENERGIES + 7]
	cmp		ecx, r8d
	jae		.n_up
	mov		r8d, ecx
	mov		al, ACT_FEED + DIR_UP
.n_up:
	cmp		byte [rdi + VIEW_CELLS + 13], CELL_FRIEND	; right
	jne		.n_right
	movzx		ecx, byte [rdi + VIEW_ENERGIES + 13]
	cmp		ecx, r8d
	jae		.n_right
	mov		r8d, ecx
	mov		al, ACT_FEED + DIR_RIGHT
.n_right:
	cmp		byte [rdi + VIEW_CELLS + 17], CELL_FRIEND	; down
	jne		.n_down
	movzx		ecx, byte [rdi + VIEW_ENERGIES + 17]
	cmp		ecx, r8d
	jae		.n_down
	mov		r8d, ecx
	mov		al, ACT_FEED + DIR_DOWN
.n_down:
	cmp		byte [rdi + VIEW_CELLS + 11], CELL_FRIEND	; left
	jne		.n_left
	movzx		ecx, byte [rdi + VIEW_ENERGIES + 11]
	cmp		ecx, r8d
	jae		.n_left
	mov		r8d, ecx
	mov		al, ACT_FEED + DIR_LEFT
.n_left:
	cmp		r8d, r9d
	ja		rest				; no friend (255), or the poorest is above the limit
	ret					; al = ACT_FEED + direction

; ---- constants (legacy-SSE memory operands must be 16-byte aligned)
	align 16
kEnemy:	db 0x02, 0xff, 0xff, 0xff, 0x02, 0xff, 0x02, 0xff, 0xff, 0xff, 0x02, 0xff, 0xff, 0xff, 0xff, 0xff	; 2 at UP/LEFT/RIGHT/DOWN lanes (window idx 7..22)
kRefill:	db 0x02, 0x00, 0x02, 0xff, 0x02, 0x00, 0xff, 0x00, 0x02, 0xff, 0x02, 0x00, 0x02, 0xff, 0xff, 0xff	; window idx 6..21: 0 at neighbours, 2 at 6/8/10/14/16/18
kTwoLo:	db 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0xff, 0x02, 0x02, 0x02	; idx 0..15, self (lane 12) excluded
kTwoHi:	db 0x02, 0x02, 0x02, 0xff, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02	; idx 9..24, self (lane 3) excluded
dir_idx:	db VIEW_UP, VIEW_RIGHT, VIEW_DOWN, VIEW_LEFT

; ---- bite_tbl: 1106 bytes, index = adjacent-enemy mask; 0 = no enemy (falls to slow)
bite_tbl:

	times 1 db 0x00
	db 0x30		; mask 0x001
	times 14 db 0x00
	db 0x33		; mask 0x010
	db 0x33		; mask 0x011
	times 46 db 0x00
	db 0x31		; mask 0x040
	db 0x30		; mask 0x041
	times 14 db 0x00
	db 0x33		; mask 0x050
	db 0x30		; mask 0x051
	times 942 db 0x00
	db 0x32		; mask 0x400
	db 0x32		; mask 0x401
	times 14 db 0x00
	db 0x32		; mask 0x410
	db 0x33		; mask 0x411
	times 46 db 0x00
	db 0x32		; mask 0x440
	db 0x31		; mask 0x441
	times 14 db 0x00
	db 0x32		; mask 0x450
	db 0x32		; mask 0x451
bite_tbl_end:

